import { test, expect } from '@playwright/test';

test.describe('Column Visibility Toggle in Table List', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should toggle visibility of columns via settings menu', async ({ page }) => {
    // Verify initial state: all columns visible
    const columnHeaders = page.getByRole('columnheader');
    await expect(columnHeaders).toHaveCount(5);

    // Verify table data is visible
    const tableData = page.getByRole('row');
    await expect(tableData).toHaveCount(10);

    // Navigate to settings menu
    const settingsMenu = page.getByRole('button', { name: /settings/i });
    await settingsMenu.click();

    // Verify settings menu is visible
    const settingsMenuOpen = page.getByRole('status', { name: /settings/i });
    await expect(settingsMenuOpen).toBeVisible();

    // Verify column visibility toggle button is present
    const toggleButton = page.getByRole('button', { name: /toggle columns/i });
    await expect(toggleButton).toBeVisible();

    // Click toggle button to hide columns
    await toggleButton.click();

    // Verify columns are hidden
    const visibleColumnHeaders = page.getByRole('columnheader');
    await expect(visibleColumnHeaders).toHaveCount(0);

    // Verify table data is still visible
    await expect(tableData).toHaveCount(10);

    // Verify settings menu is still open
    await expect(settingsMenuOpen).toBeVisible();

    // Click toggle button again to show columns
    await toggleButton.click();

    // Verify columns are visible again
    await expect(visibleColumnHeaders).toHaveCount(5);

    // Verify table data is still visible
    await expect(tableData).toHaveCount(10);

    // Verify settings menu is closed
    const settingsMenuClosed = page.getByRole('status', { name: /closed/i });
    await expect(settingsMenuClosed).toBeVisible();
  });

  test('should handle edge case: no columns available to toggle', async ({ page }) => {
    // Navigate to table list with no columns
    await page.goto('/table-list/empty');

    // Verify no column headers are present
    const columnHeaders = page.getByRole('columnheader');
    await expect(columnHeaders).toHaveCount(0);

    // Verify table data is still visible
    const tableData = page.getByRole('row');
    await expect(tableData).toHaveCount(0);

    // Navigate to settings menu
    const settingsMenu = page.getByRole('button', { name: /settings/i });
    await settingsMenu.click();

    // Verify settings menu is visible
    const settingsMenuOpen = page.getByRole('status', { name: /settings/i });
    await expect(settingsMenuOpen).toBeVisible();

    // Verify column visibility toggle button is present
    const toggleButton = page.getByRole('button', { name: /toggle columns/i });
    await expect(toggleButton).toBeVisible();

    // Click toggle button
    await toggleButton.click();

    // Verify no columns are visible
    const visibleColumnHeaders = page.getByRole('columnheader');
    await expect(visibleColumnHeaders).toHaveCount(0);

    // Verify table data is still visible
    await expect(tableData).toHaveCount(0);

    // Verify settings menu is still open
    await expect(settingsMenuOpen).toBeVisible();

    // Verify no error message is displayed
    const errorMessage = page.getByText(/no columns to toggle/i);
    await expect(errorMessage).toBeVisible();

    // Verify settings menu is closed
    const settingsMenuClosed = page.getByRole('status', { name: /closed/i });
    await expect(settingsMenuClosed).toBeVisible();
  });
});
